    const score = w.lat*normLat + w.hlth*normHealth + w.cost*normCost + w.load*normLoad + w.size*normSize + w.prio*normPrio;
    return { score, factors: { lat:normLat, hlth:normHealth, cost:normCost, load:normLoad, size:normSize, prio:normPrio } };
  };

  // 排序键：保留 P1.3/P1.7 penalty 原样（审核班 #3 必补项——整替时不能丢 429 冷却/熔断降权）
  const routed = routedBase.map(u => {
    const jitter = 0.7 + 0.6 * Math.random(); // P2.2：存值供审计（当次抖动可复算）
    let key = state.ewma[u.id] * (u.bias || 1) * jitter; // 现三因子（生产态排序键，含 p2c 抖动去粘滞）
